    implementationRequested && !isQuotedOrCommentedSource(sourceText(line)) ? 1 : 0,
    directIdentity,
    requestedProperty,
    conditionRequested && looksLikeCondition(line) ? 1 : 0,
    authority,
    conditionRequested && looksLikeInstanceCondition(line) ? 1 : 0,
    declarationShape,
